__NUXT_JSONP__("/inclusion/eventos", (function(a,b,c,d,e,f,g,h){return {data:[{eventos:[{slug:"presentan_informe_con_diagnostico_y_propuestas_para_dignificar_la_labor_de_las_trabajadoras_agricolas",title:"Presentan informe con diagnóstico y propuestas para dignificar la labor de las trabajadoras agrícolas",date:"2025-10-01T21:15:12.605Z",img:"https:\u002F\u002Fucarecdn.com\u002F880400a6-0330-4ab6-9eca-1e8727446864\u002F-\u002Fpreview\u002F",autor:d,category:a,extracto:"Sembrando el cambio: Hacia un futuro justo para las trabajadoras agrícolas en México, es un documento elaborado por UNIDAS —alianza integrada por Ethos, Oxfam México, ProDESC y Fundación Avina—, que expone el panorama de precariedad que enfrentan las jornaleras agrícolas y propone acciones para garantizarles un trabajo justo y digno.",toc:[],dir:b,path:"\u002Feventos\u002Fpresentan_informe_con_diagnostico_y_propuestas_para_dignificar_la_labor_de_las_trabajadoras_agricolas",extension:c,createdAt:"2025-11-25T01:24:03.258Z",updatedAt:"2025-11-25T01:24:03.259Z"},{slug:"presentan_unidas_alianza_para_la_defensa_de_los_derechos_laborales_de_las_mujeres_trabajadoras",title:"Presentan UNIDAS, alianza para la defensa de los derechos laborales de las mujeres trabajadoras ",date:"2025-03-25T23:36:26.298Z",img:"https:\u002F\u002Fucarecdn.com\u002Ff7975a04-d37b-443e-b748-60caefa261b1\u002F","img-alt":"UNIDAS",autor:d,category:a,extracto:"En 2024, solo el 46% de las mujeres en edad de trabajar participaron en el mercado de trabajo. El 55.6% de ellas lo hace en condiciones de informalidad. Por cada 100 pesos que gana un hombre, una mujer percibe solo 85. ",toc:[],dir:b,path:"\u002Feventos\u002Fpresentan_unidas_alianza_para_la_defensa_de_los_derechos_laborales_de_las_mujeres_trabajadoras",extension:c,createdAt:e,updatedAt:e},{slug:"las_mujeres_en_el_sector_agricola_enfrentan_una_sobrecarga_de_trabajo_de_cuidados",title:"Las mujeres en el sector agrícola enfrentan una sobrecarga de trabajo de cuidados",date:"2025-03-19T23:26:41.860Z",img:"https:\u002F\u002Fucarecdn.com\u002Fc0432d79-1c4e-4cd7-b5b0-85234c5ebea9\u002F-\u002Fcrop\u002F1441x918\u002F9,107\u002F-\u002Fpreview\u002F","img-alt":f,autor:d,category:a,extracto:"En el Seminario Mujeres en el Sector Agrícola Mexicano, Mónica Corona, directora de Inclusión y Desarrollo Sostenible de Ethos, expresó que la sobrecarga de cuidados que viven las mujeres trabajadoras del sector agrícola impacta negativamente en sus condiciones laborales y de vida. ",toc:[],dir:b,path:"\u002Feventos\u002Flas_mujeres_en_el_sector_agricola_enfrentan_una_sobrecarga_de_trabajo_de_cuidados",extension:c,createdAt:e,updatedAt:e},{slug:"en_mexico_6-8_millones_de_ninas_y_ninos_de_0_a_5_anos_carecen_de_servicios_de_cuidado_y_educacion",title:"En México, 6.8 millones de niñas y niños de 0 a 5 años carecen de servicios de cuidado y educación",date:"2025-03-19T23:23:39.221Z",img:"https:\u002F\u002Fucarecdn.com\u002Fb9a47c13-ff38-41a9-815d-961bdb92237a\u002F","img-alt":f,autor:d,category:a,extracto:"En conferencia de prensa, especialistas de Early Institute, Ethos Innovación en Políticas Públicas y el Centro de Investigación Económica y Presupuestaria (CIEP) formularon una serie de recomendaciones a gobiernos e instituciones para revertir rezagos en materia de cuidados y educación de la primera infancia.",toc:[],dir:b,path:"\u002Feventos\u002Fen_mexico_6-8_millones_de_ninas_y_ninos_de_0_a_5_anos_carecen_de_servicios_de_cuidado_y_educacion",extension:c,createdAt:g,updatedAt:g},{slug:"el_cuidado_de_la_primera_infancia_requiere_corresponsabilidad",title:"El cuidado de la primera infancia requiere corresponsabilidad",date:"2025-03-04T19:54:23.230Z",img:"https:\u002F\u002Fucarecdn.com\u002F31d881bb-8089-4d39-b0e6-e4ed4e961deb\u002F","img-alt":f,autor:d,category:a,extracto:"Para que el cuidado de la primera infancia deje de depender casi exclusivamente de las mujeres, se requiere articular políticas entre el gobierno, las empresas, la comunidad y las familias, consideró Mónica Corona, directora de Inclusión y Desarrollo Sostenible en Ethos, en un foro organizado por el Senado de la República.",toc:[],dir:b,path:"\u002Feventos\u002Fel_cuidado_de_la_primera_infancia_requiere_corresponsabilidad",extension:c,createdAt:h,updatedAt:h},{slug:"presentacion_riesgos_de_corrupcion_en_programas_sociales",title:"PRESENTACIÓN RIESGOS DE CORRUPCIÓN EN PROGRAMAS SOCIALES",date:"2021-09-03T15:21:47.278Z",img:"https:\u002F\u002Fucarecdn.com\u002F9cbdf8c0-ac8e-4b7f-90bf-30b30112cc52\u002F",autor:d,link:"https:\u002F\u002Fwww.ethos.org.mx\u002Fwp-content\u002Fuploads\u002F2021\u002F09\u002FPresentacion-Evento-Riesgos-de-Corrupcion-2021-31-08.pdf",category:a,extracto:"Los programas sociales es que son instrumentos de políticas públicas pensados para resolver los problemas sociales y, en particular, la pobreza. ",toc:[],dir:b,path:"\u002Feventos\u002Fpresentacion_riesgos_de_corrupcion_en_programas_sociales",extension:c,createdAt:"2023-06-19T05:12:00.731Z",updatedAt:"2022-09-15T15:48:00.236Z"},{slug:"identificar_riesgos_de_corrupcion_permite_ajustar_los_programas_sociales_para_aumentar_su_efectividad",title:"Identificar riesgos de corrupción permite ajustar los programas sociales para aumentar su efectividad",date:"2021-08-31T15:25:10.932Z",img:"https:\u002F\u002Fucarecdn.com\u002Fe48f8d10-d196-4adc-ad2a-e410185de2d6\u002F",autor:d,category:a,extracto:"Con el objetivo de dar a conocer el trabajo realizado desde la sociedad civil para desarrollar metodologías que permitan identificar riesgos de corrupción en programas sociales, se ha trabajado en el diseño de herramientas amigables para que la ciudadanía pueda realizar este tipo de acciones de vigilancia, y el propósito final es incentivar que los programas sociales tengan mejores resultados.",toc:[],dir:b,path:"\u002Feventos\u002Fidentificar_riesgos_de_corrupcion_permite_ajustar_los_programas_sociales_para_aumentar_su_efectividad",extension:c,createdAt:"2023-06-19T05:12:00.079Z",updatedAt:"2022-09-15T15:48:00.234Z"},{slug:"pobreza_en_mexico_los_retos_que_trajo_consigo_la_covid-19",title:"Pobreza en México: los retos que trajo consigo la COVID-19",date:"2021-06-07T22:29:17.737Z",img:"https:\u002F\u002Fucarecdn.com\u002F61b1cdbe-1520-463b-ae47-1b495c098e56\u002F",autor:"Ethos Laboratorio de Politicas Publicas ",link:"https:\u002F\u002Fwww.youtube.com\u002Fwatch?v=nfHGVJf8U4w",category:a,extracto:"La crisis que ocasionó la COVID-19 es algo sin precedentes que ha afectado a toda la ciudadanía, pero de manera particular a las poblaciones más vulnerables, señaló Laure Delalande, directora del área de Innovación de Ethos Laboratorio de Políticas Públicas, al dar la bienvenida al webinario «Pobreza en México: perspectivas del impacto de la COVID-19», que tiene como objetivo comprender qué pasa con la pobreza en México y reflexionar sobre las perspectivas para México en este contexto.",toc:[],dir:b,path:"\u002Feventos\u002Fpobreza_en_mexico_los_retos_que_trajo_consigo_la_covid-19",extension:c,createdAt:"2023-06-19T05:12:00.700Z",updatedAt:"2022-08-30T02:27:13.004Z"}],total:[{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("inclusion","\u002Feventos",".md","Ethos","2025-04-23T06:21:15.374Z","Mónica Corona, Ethos","2025-04-23T06:21:15.373Z","2025-04-23T06:21:15.372Z")));